(37810, 'Numbers 15:14', 'Numbers', 15, 14, 'همدارنګه هغه پردي خلک چې ستاسو په منځ کې اوسیږي، که هغوی د موقت وخت دپاره وي یا تلپاتې وي هم باید د دغو مقرراتو څخه پیروي وکړي.', 'همدارنګه هغه پردی خلک چې ستاسو په منج کې اوسیزی، که هغوی د موقت وخت دپاره وی یا تلپاتې وی هم باید د دغو مقرراتو چخه پیروی وکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_15_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37811, 'Numbers 15:20', 'Numbers', 15, 20, 'کله چې تاسو ډوډۍ پخوئ، نو د لومړنۍ پېړې ډوډۍ چې د نوې غلې دانې څخه پخیږي هغه دې څښتن ته د ځانګړې نذرانې په توګه وړاندې شي. دا دې په هماغه ډول وړاندې شي لکه څنګه چې د غوبل شویو غلو دانو څخه تیاره شوې ځانګړې نذرانه وړاندې کیږي.', 'کله چې تاسو دودی پخوی، نو د لومرنی پېرې دودی چې د نوې غلې دانې چخه پخیزی هغه دې چشتن ته د جانګرې نذرانې په توګه وراندې شی. دا دې په هماغه دول وراندې شی لکه چنګه چې د غوبل شویو غلو دانو چخه تیاره شوې جانګرې نذرانه وراندې کیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_15_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37812, 'Numbers 15:21', 'Numbers', 15, 21, 'دا ځانګړی سوغات دې د تل دپاره د هغې ډوډۍ څخه څښتن ته ورکول کیږي چې تاسو یې پخوئ.', 'دا جانګری سوغات دې د تل دپاره د هغې دودی چخه چشتن ته ورکول کیزی چې تاسو یې پخوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_15_21.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(37813, 'Numbers 15:22', 'Numbers', 15, 22, 'خو فرض کړئ که چېرې یو څوک په سهوې سره د دغو مقرراتو څخه د ځینو په عملي کولو کې چې څښتن موسی ته ورکړي دي، بې پروایي وکړي', 'خو فرض کری که چېرې یو چوک په سهوې سره د دغو مقرراتو چخه د جینو په عملی کولو کې چې چشتن موسی ته ورکری دی، بې پروایی وکری', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_15_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37814, 'Numbers 15:23', 'Numbers', 15, 23, 'او فرض کړئ چې په راتلونکې کې د هغو ټولو شیانو په سرته رسولو کې چې څښتن د موسی په وسیله د هغو حکم کړی دی قوم بې پروایي وکړي.', 'او فرض کری چې په راتلونکې کې د هغو تولو شیانو په سرته رسولو کې چې چشتن د موسی په وسیله د هغو حکم کری دی قوم بې پروایی وکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_15_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37815, 'Numbers 15:24', 'Numbers', 15, 24, 'که چېرې دا کار په سهوې او په بې خبرۍ سره د قوم له خوا وشي، نو باید ټول قوم یو غویی د سوځېدونکې نذرانې دپاره چې بوی یې په څښتن باندې ښه لګیږي وړاندې کړي. دا نذرانه دې د پورته یادې شوې غلې دانې د نذرانې او څښلو د نذرانې سره یوځای او د یو سېرلي سره چې د ګناه د نذرانې په توګه وړاندې کیږي، وړاندې شي.', 'که چېرې دا کار په سهوې او په بې خبری سره د قوم له خوا وشی، نو باید تول قوم یو غویی د سوجېدونکې نذرانې دپاره چې بوی یې په چشتن باندې شه لګیزی وراندې کری. دا نذرانه دې د پورته یادې شوې غلې دانې د نذرانې او چشلو د نذرانې سره یوجای او د یو سېرلی سره چې د ګناه د نذرانې په توګه وراندې کیزی، وراندې شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_15_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37816, 'Numbers 15:25', 'Numbers', 15, 25, 'کاهن به د اسراییلو د ټول قوم دپاره کفاره ادا کړي او هغوی به وبخښل شي، ځکه چې دا کار په قصدي توګه نه ؤ شوی او هغوی څښتن ته د خپلې غلطۍ دپاره یوه داسې نذرانه چې په اور باندې تیاریږي او د ګناه یوه نذرانه راوړله.', 'کاهن به د اسراییلو د تول قوم دپاره کفاره ادا کری او هغوی به وبخشل شی، جکه چې دا کار په قصدی توګه نه و شوی او هغوی چشتن ته د خپلې غلطی دپاره یوه داسې نذرانه چې په اور باندې تیاریزی او د ګناه یوه نذرانه راورله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_15_25.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37817, 'Numbers 15:26', 'Numbers', 15, 26, 'د اسراییلو ټول قوم او هغه پردي خلک به چې د هغوی په منځ کې اوسیږي وبخښل شي، ځکه چې ټول په دې غلطۍ کې شامل وو.', 'د اسراییلو تول قوم او هغه پردی خلک به چې د هغوی په منج کې اوسیزی وبخشل شی، جکه چې تول په دې غلطی کې شامل وو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_15_26.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37818, 'Numbers 15:27', 'Numbers', 15, 27, 'خو که چېرې ستاسو څخه یو تن په سهوې سره ګناه وکړي، نو باید یوه یو کلنه وزه د ګناه د نذرانې په توګه قرباني کړي.', 'خو که چېرې ستاسو چخه یو تن په سهوې سره ګناه وکری، نو باید یوه یو کلنه وزه د ګناه د نذرانې په توګه قربانی کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_15_27.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
